public static TFMListNode makeNode(TFMListId _listId, Version _version, RefRecId _parent, XmlElement _node)
{
    TFMListNode			listNode;
    TFMListAttribute	listAttribute;
    TFMNodeName			nodeName = _node.name();
    XmlNamedNodeMap		nodeMap;
    XmlNode				attrNode;

    listNode.NodeName = nodeName;
    listNode.ParentNode = _parent;
    listNode.ListId		= _listId;
    listNode.Version	= _version;
    listNode.LineNum	= TFMListNode::nextLineNum(_parent);
    listNode.insert();

    nodeMap = _node.attributes();

    attrNode = nodeMap.nextNode();

    while (attrNode)
    {
        listAttribute.AttributeName = attrNode.name();
        listAttribute.Value			= attrNode.innerText();
        listAttribute.ParentNode	= listNode.RecId;
        listAttribute.insert();
        attrNode = nodeMap.nextNode();
    }

    return listNode;
}

public void write()
{
    this.CustomComponentParentNode = className2Id(this.NodeName);
    super();
}

public static TFMListNode addNode(str _nodeName, RefRecId _parent, TFMListId _listId, Version _version)
{
    TFMListNode			listNode;

    select firstonly listNode where listNode.RecId == _parent;

    listNode.NodeName	= _nodeName;
    listNode.ParentNode = _parent;  
    listNode.ListId		= _listId;
    listNode.Version	= _version;
    listNode.LineNum	= TFMListNode::nextLineNum(_parent);
    listNode.insert();

    return listNode;
}

public static void pasteNodeFromNode(TFMListNode _nodeFrom, TFMListNode _parentTo)
{
    TFMListNode			listNodeTo;
    TFMListNode			listNodeFromChildren;
    TFMListAttribute	attrTo;
    MapEnumerator		attrs = _nodeFrom.Attributes().getEnumerator();

    listNodeTo.NodeName	= _nodeFrom.NodeName;
    listNodeTo.ParentNode = _parentTo.RecId;
    listNodeTo.LineNum	= TFMListNode::nextLineNum(_parentTo.RecId);
    listNodeTo.ListId	= _parentTo.ListId;
    listNodeTo.Version	= _parentTo.Version;
    listNodeTo.insert();

    while (attrs.moveNext())
    {
        attrTo.AttributeName	= attrs.currentKey();
        attrTo.Value			= attrs.currentValue();
        attrTo.ParentNode		= listNodeTo.RecId;
        attrTo.insert();
    }
    while select listNodeFromChildren where listNodeFromChildren.ParentNode == _nodeFrom.RecId
    {
        TFMListNode::pasteNodeFromNode(listNodeFromChildren,listNodeTo);
    }
}

	public static real nextLineNum(RefRecId _parent)
    {
        TFMListNode listNode;
        select firstonly listnode order by LineNum desc where listnode.ParentNode == _parent;

        return listNode.lineNum +1;

    }

	public Map Attributes()
    {
        TFMListAttribute attributes;
        Map					resAttr = new Map(Types::String, Types::String);
		while select attributes where attributes.ParentNode == this.RecId
        {
            resAttr.insert(attributes.AttributeName, attributes.Value);
        }
        return resAttr;
    }

public void createOrUpdateParameter(TFMAttributeName _attributeName, str _value)
{
    TFMListattribute attributeNode;

    ttsbegin;
    attributeNode = TFMListAttribute::Find(this.RecId,_attributeName,true);

    attributeNode.AttributeName = _attributeName;
    attributeNode.ParentNode	= this.RecId;
    attributeNode.Value			= _value;
    attributeNode.write();

    ttscommit;
}

	public str getXPath()
    {
        TFMListNode			listNode;
        str					path;

		if (!this.ParentNode)
        {
            return this.NodeName;
        }
        select firstonly listNode where listNode.recId == this.ParentNode;

        path = listNode.getXPath() + '/' + this.NodeName;

        return path;
    }

public static TFMListNode Find(RecId _recid, boolean _selectForUpdate = false)
{
    TFMListNode listNode;
    listNode.selectForUpdate(_selectForUpdate);

    select firstonly listNode where listNode.RecId == _recid;

    return listNode;
}

public static void MoveUp(RefRecId _nodeToMove)
{
    TFMListNode listNodeAbove;
    TFMListNode	listNodeChosen;
    LineNum		tempLineNum;
    ttsbegin;
    select forupdate listNodeChosen where listNodeChosen.RecId == _nodeToMove;
    select forupdate listNodeAbove order by LineNum desc where listNodeAbove.ParentNode == listNodeChosen.parentNode && listNodeAbove.LineNum < listNodeChosen.LineNum;
    if (listNodeAbove)
    {
        tempLineNum = listNodeAbove.LineNum;

        listNodeAbove.LineNum = listNodeChosen.LineNum;
        listNodeChosen.LineNum = tempLineNum;
        listNodeAbove.update();
        listNodeChosen.update();
    }
    ttscommit;
}

public static void MoveDown(RefRecId _nodeToMove)
{
    TFMListNode listNodeBelow;
    TFMListNode	listNodeChosen;
    LineNum		tempLineNum;
    ttsbegin;
    select forupdate listNodeChosen where listNodeChosen.RecId == _nodeToMove;
    select forupdate listNodeBelow order by LineNum asc where listNodeBelow.ParentNode == listNodeChosen.parentNode && listNodeBelow.LineNum > listNodeChosen.LineNum;

    if (listNodeBelow)
    {
        tempLineNum = listNodeBelow.LineNum;

        listNodeBelow.LineNum = listNodeChosen.LineNum;
        listNodeChosen.LineNum = tempLineNum;
        listNodeBelow.update();
        listNodeChosen.update();
    }
    ttscommit;
}

    public str valueParent()
    {
        TFMListNode		listSuperNode;
        RecId			parent;

		if (this.NodeName != 'value' || !this.ParentNode)
        {
            return '';
        }
        select firstonly listSuperNode where listSuperNode.RecId == this.ParentNode;

        parent = listSuperNode.ParentNode;
		if (!parent)
        {
            return '';
        }

        select firstonly listSuperNode where listSuperNode.RecId == parent;
        return listSuperNode.NodeName;
    }
